fn overlap(a:[f64;4],b:[f64;4])->f64{(a[2].min(b[2])-a[0].max(b[0])).max(0.0)*(a[3].min(b[3])-a[1].max(b[1])).max(0.0)}
fn exit(r:[f64;4],p:Pt,q:Pt)->Pt{let(dx,dy)=(q.0-p.0,q.1-p.1);let mut t=1.0_f64;for(d,a,b)in[(dx,r[0]-p.0,r[2]-p.0),(dy,r[1]-p.1,r[3]-p.1)]{if d.abs()>=1e-6{t=t.min((a/d).max(b/d))}}(p.0+dx*t,p.1+dy*t)}
impl Plan<'_,'_>{fn callouts(&mut self,v:&Value)->Result<(),String>{let Some(cs)=v["callouts"].as_array()else{return Ok(())};let dur=num(v,"end")-num(v,"start");let times:Vec<f64>=cs.iter().map(|c|c["at"].as_f64().map(|a|(a-num(v,"start")).min(dur-1.0).max(0.15)).unwrap_or(0.4)).collect();let life:Vec<(f64,f64)>=times.iter().enumerate().map(|(i,&t)|(t,(dur-0.3).min(t+2.8).min(times.get(i+3).map(|n|(t+1.6).max(n+0.1)).unwrap_or(1e9)))).collect();let rect=|n:&Node|{let(x,y,w,h)=n.frame;[x,y,x+w,y+h]};let role=|n:&Node|!matches!(n.kind,"heading"|"hero"|"heroLeft"|"statement"|"sub"|"eyebrow"|"pictFrame"|"band"|"image")||!label(&n.item,"label").is_empty();let mut still:Vec<[f64;4]>=self.nodes.iter().filter(|n|role(n)).map(|n|{let r=rect(n);[r[0]-14.0,r[1]-14.0,r[2]+14.0,r[3]+14.0]}).collect();for e in &self.edges{let(a,b)=(&self.nodes[e.a],&self.nodes[e.b]);let sd=|n:&Node,s:&str|{let(x,y,w,h)=n.frame;match s{"l"=>(x,y+h/2.0),"r"=>(x+w,y+h/2.0),"t"=>(x+w/2.0,y),_=>(x+w/2.0,y+h)}};let(sa,sb)=e.sides.unwrap_or(("r","l"));let(p,q)=(sd(a,sa),sd(b,sb));still.push([p.0.min(q.0)-10.0,p.1.min(q.1)-10.0,p.0.max(q.0)+10.0,p.1.max(q.1)+10.0]);}let explicit=self.nodes.iter().any(|n|n.item.get("pictureSlot").is_some());let anchors:Vec<usize>=self.nodes.iter().enumerate().filter(|(_,n)|if explicit{n.item.get("pictureSlot").is_some()}else{n.item["grp"]=="item"&&!label(&n.item,"label").is_empty()&&n.item["parent"].is_null()}).map(|(i,_)|i).collect();let mut placed:Vec<([f64;4],(f64,f64),Option<usize>,usize)>=Vec::new();let mut last=BTreeMap::new();for(i,c)in cs.iter().enumerate(){let ai=c["on"].as_u64().and_then(|on|if explicit{anchors.iter().copied().find(|&a|self.nodes[a].item["pictureSlot"]==on)}else{anchors.get(on as usize).copied()});let a=ai.map(|a|self.nodes[a].frame);let y0=if label(v,"title").is_empty(){36.0}else{self.s.top-12.0};let(ac,hw,hh)=a.map(|(x,y,w,h)|((x+w/2.0,y+h/2.0),w/2.0,h/2.0)).unwrap_or(((self.s.w/2.0,(y0+self.s.bottom+4.0)/2.0),260.0,160.0));let text=label(c,"text");let seed=format!("{text}:{i}").encode_utf16().fold(2166136261_u32,|h,c|(h ^ c as u32).wrapping_mul(16777619)) as i32;let w=self.pillw(text,22.0);let mut best:Option<(f64,[f64;4],usize)>=None;for(di,(dx,dy))in [(1.0_f64,-0.7),(-1.0,-0.7),(1.0,0.75),(-1.0,0.75),(0.35,-1.0),(-0.35,-1.0),(0.35,1.0),(-0.35,1.0),(1.0,0.0),(-1.0,0.0)].into_iter().enumerate(){for(ri,gap)in[40.0,80.0,125.0].into_iter().enumerate(){let x=ac.0+dx*if dx.abs()<0.5{hw*0.6+w*0.3}else{hw+gap+w/2.0};let y=ac.1+dy*(hh+gap+22.0);let r=[x-w/2.0,y-22.0,x+w/2.0,y+22.0];if r[0]<40.0||r[1]<y0||r[2]>self.s.w-40.0||r[3]>self.s.bottom+4.0{continue}let mut cost=still.iter().map(|&o|overlap(r,o)*3.0).sum::<f64>();for(p,l,pa,pd)in &placed{if l.0<life[i].1+0.3&&l.1>life[i].0-0.3{cost+=overlap(r,*p)*4.0;if *pa==ai&&*pd==di{cost+=4000.0}}}if ai.is_some(){for k in 1..8{let p=(x+(ac.0-x)*k as f64/8.0,y+(ac.1-y)*k as f64/8.0);for(ni,n)in self.nodes.iter().enumerate(){let(nx,ny,nw,nh)=n.frame;if Some(ni)!=ai&&role(n)&&p.0>nx&&p.0<nx+nw&&p.1>ny&&p.1<ny+nh{cost+=3000.0}}}}if last.get(&ai)==Some(&di){cost+=2500.0}cost+=ri as f64*300.0+if dy==0.0{400.0}else{0.0}+((seed>>(di%16))&7) as f64*60.0;if best.as_ref().is_none_or(|b|cost<b.0){best=Some((cost,r,di));}}}let Some((_,r,di))=best else{return Err(format!("no valid callout position for {text:?}"))};last.insert(ai,di);let tilt=(((seed>>3)&7) as f64-3.5)*0.7;let ti=self.add("callout",(r[0],r[1],w,44.0),&json!({"label":text,"icon":"","tone":c["tone"]}),"detail",json!({"fs":22,"fixA":life[i].0,"gone":life[i].1,"tilt":tilt,"callout":1}));placed.push(([r[0]-18.0,r[1]-18.0,r[2]+18.0,r[3]+18.0],life[i],ai,di));if let Some(ai)=ai{let tc=((r[0]+r[2])/2.0,(r[1]+r[3])/2.0);let(mut from,mut to)=(exit(r,tc,ac),exit(rect(&self.nodes[ai]),ac,tc));let(u,v)=(to.0-from.0,to.1-from.1);let len=u.hypot(v);let len=if len==0.0{1.0}else{len};from.0+=u/len*6.0;from.1+=v/len*6.0;to.0-=u/len*4.0;to.1-=v/len*4.0;let bow=36.0_f64.min(len*0.22)*if seed&1!=0{1.0}else{-1.0};let mid=((from.0+to.0)/2.0-v/len*bow,(from.1+to.1)/2.0+u/len*bow);let line:Vec<Value>=(0..=16).map(|q|{let t=q as f64/16.0;let z=1.0-t;json!({"x":z*z*from.0+2.0*z*t*mid.0+t*t*to.0,"y":z*z*from.1+2.0*z*t*mid.1+t*t*to.1})}).collect();self.edge(ti,ai,"leader",Some(("l","r")));self.edges.last_mut().unwrap().extra=json!({"line":line,"fixA":life[i].0+0.05,"gone":life[i].1-0.1});}}Ok(())}}
